await (async page => { await page.reload(); await page.locator("#helpBtn").click(); const helpText=await page.locator("#modalBody").innerText(); await page.locator("#modalOkay").click(); const before={ball:await page.locator("#ballOn").innerText(),down:await page.locator("#downDistance").innerText()}; await page.evaluate(() => { state.playClock=1; }); await page.waitForTimeout(1400); const after={clock:await page.locator("#playClock b").innerText(),ball:await page.locator("#ballOn").innerText(),down:await page.locator("#downDistance").innerText(),feed:await page.locator("#feed").innerText()}; return {helpMentionsClock:helpText.includes("25-second"),before,after}; })(page);
```

